  --faint: #d8d7d0;
  --accent: #8fa8bc;

  width: 340px !important;
  max-width: 100%;
  max-height: 82vh !important;
  padding: 26px 30px 26px !important;
  background: var(--bg) !important;
  border: 1px solid var(--faint) !important;
  border-radius: 6px !important;
  box-shadow: 0 12px 34px rgba(60, 60, 50, .08) !important;
  font-family: 'Noto Sans SC', sans-serif !important;
  font-size: 11px !important;
  color: var(--ink);
  overflow: visible !important;
}

.xt-content { max-height: calc(82vh - 52px) !important; overflow-x: hidden !important; scrollbar-width: none !important; }
.xt-content::-webkit-scrollbar { display: none !important; }
.xt-header { display: none !important; }

/* 顶部标签 */
.xt-content > .xt-row:nth-of-type(1) { padding: 0 2px 0 !important; }
.xt-text-dayLabel, .xt-text-currentDate {
  background: none !important; border: none !important; padding: 0 0 12px !important;
  font-size: 8px !important; font-weight: 400 !important; letter-spacing: .34em !important; color: var(--sub) !important;
  border-bottom: 1px solid var(--faint) !important; border-radius: 0 !important;
}
.xt-text-dayLabel::before { content: "展示個体 · "; }
.xt-text-currentDate { text-align: right !important; }

/* ---------- 左：水槽 ---------- */
.xt-content > .xt-row:nth-of-type(2) { align-items: stretch !important; gap: 12px !important; margin: 20px 0 16px !important; }
.xt-text-tankPanel {
  flex: 0 0 42% !important;
  position: relative !important;
  min-height: 168px !important; margin: 0 !important; padding: 0 !important;
  background: linear-gradient(180deg, #eef3f6, #dde8ee) !important;
  border: 1px solid var(--faint) !important; border-radius: 4px !important;
  overflow: hidden !important; color: transparent !important; font-size: 0 !important;
}
/* 鱼（SVG） */
.xt-text-tankPanel::before {
  content: "" !important; position: absolute !important; top: 44% !important; left: 18% !important;
  width: 64px !important; height: 30px !important;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 30'><path d='M6 15 Q16 2 34 4 Q52 6 50 15 Q52 24 34 26 Q16 28 6 15 Z' fill='%238fa8bc'/><path d='M6 15 L0 6 L2 15 L0 24 Z' fill='%238fa8bc'/><circle cx='42' cy='12' r='1.6' fill='%23fdfdfb'/></svg>") no-repeat center/contain !important;
  transition: transform .6s ease !important;
}
/* 投喂后游走 */
#xt-t1:checked ~ .xt-content .xt-text-tankPanel::before {
  animation: swim 4.5s ease-in-out infinite !important;
}
@keyframes swim {
  0%, 100% { transform: translate(0, 0) scaleX(1); }
  48% { transform: translate(70px, -14px) scaleX(1); }
  52% { transform: translate(74px, -12px) scaleX(-1); }
}
/* 气泡 */
.xt-text-tankPanel::after {
  content: "" !important; position: absolute !important; bottom: 12px !important; left: 30% !important;
  width: 5px !important; height: 5px !important; border-radius: 50% !important;
  border: 1px solid rgba(143, 168, 188, .6) !important;
  box-shadow: 12px -18px 0 -1px rgba(143,168,188,.45), 22px -34px 0 -2px rgba(143,168,188,.35) !important;
  animation: bubble 3s ease-in infinite !important;
}
@keyframes bubble { 0% { transform: translateY(0); opacity: 1; } 100% { transform: translateY(-60px); opacity: 0; } }

/* ---------- 右：图鉴信息 ---------- */
.xt-text-infoPanel {
  flex: 1 !important; background: none !important; border: none !important; padding: 2px 0 !important; margin: 0 !important;
  font-size: 10px !important; line-height: 1.9 !important; color: #4a473f !important; letter-spacing: .02em !important;
}
.xt-text-infoPanel b, .xt-text-infoPanel strong { color: var(--ink); font-weight: 500; }

/* ---------- 观察记录 ---------- */
.xt-text-observeTitle {
  background: none !important; border: none !important; padding: 0 2px 8px !important; margin: 0 !important;
  font-size: 8px !important; letter-spacing: .34em !important; color: var(--accent) !important;
  border-bottom: 1px solid var(--faint) !important; border-radius: 0 !important;
}
.xt-text-observeLog {
  background: none !important; border: none !important; padding: 12px 2px 16px !important; margin: 0 !important;
  font-family: 'Noto Serif SC', serif !important; font-weight: 300 !important;
  font-size: 11.5px !important; line-height: 2.1 !important; color: #3a372f !important; letter-spacing: .03em !important;
  border-bottom: 1px solid var(--faint) !important; border-radius: 0 !important;
}
/* 投喂后追加的一行 */
.xt-text-observeLog::after {
  content: "" !important; display: block !important;
  font-family: 'Noto Sans SC', sans-serif !important;
  font-size: 10px !important; color: var(--accent) !important; letter-spacing: .04em !important;
  max-height: 0 !important; overflow: hidden !important; opacity: 0 !important;
  transition: max-height .6s ease, opacity .5s ease, margin .5s ease !important;
}
#xt-t1:checked ~ .xt-content .xt-text-observeLog::after {
  content: "追加观察：投喂后活跃异常，疑似在等人。";
  max-height: 40px !important; opacity: 1 !important; margin-top: 8px !important;
}

/* 投喂按钮 */
.xt-action-1 {
  display: block !important; width: 100% !important;
  background: none !important; border: 1px solid var(--faint) !important; border-radius: 999px !important;
  padding: 8px 0 !important; margin: 4px 0 14px !important;
  text-align: center !important; font-size: 8.5px !important; font-weight: 400 !important;
  letter-spacing: .34em !important; color: var(--sub) !important; cursor: pointer !important;
  transition: color .3s ease, border-color .3s ease !important;
}
.xt-action-1::after { content: "餌やり · 投喂今天的你"; }
.xt-action-1:hover { color: var(--ink); border-color: var(--sub); }
#xt-t1:checked ~ .xt-content .xt-action-1 { color: var(--accent); border-color: var(--accent); }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "もう十分 · 吃过了"; }

.xt-footer {
  background: none !important; border: none !important; padding: 12px 0 0 !important; margin: 0 !important;
  border-top: 1px solid var(--faint) !important; border-radius: 0 !important;
  text-align: center !important; font-size: 7px !important; font-weight: 300 !important;
  letter-spacing: .44em !important; color: var(--faint) !important;
}

