@font-face{font-family:"ZSFT-br";src:url("https://fontsapi.zeoseven.com/br/medium.woff2") format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"ZSFT-br";src:url("https://fontsapi.zeoseven.com/br/main.woff2") format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"ZSFT-br";src:url("https://fontsapi.zeoseven.com/br/semi-bold.woff2") format("woff2");font-weight:600;font-display:swap}

/* App-shell reset: removes P1's navy gutter, text panels and scroll lock. */
.xt-root,.xt-root *{box-sizing:border-box}
.xt-root{
  --ink:#14223b;--ink-soft:#33435e;--ink-muted:#62708a;--rule:rgba(20,48,89,.38);
  width:min(100%,942px)!important;margin:0 auto!important;padding:0!important;
  overflow-x:hidden!important;overflow-y:auto!important;overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;touch-action:pan-y;
  color:var(--ink)!important;background:#edf0f4!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;
  font-family:"KingHwaOldSong","Noto Serif SC",serif!important;font-weight:400;line-height:1.7;
  text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased
}
.xt-content{display:block!important;margin:0!important;padding:0!important;overflow:visible!important;background:transparent!important}
.xt-card,.xt-row,.xt-text,.xt-divider,.xt-footer{min-width:0}
.xt-card{
  margin:0!important;padding:0!important;overflow:visible!important;color:inherit!important;
  background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important
}
.xt-text{
  min-height:0!important;margin:0!important;padding:0!important;overflow-wrap:anywhere;white-space:pre-wrap;
  background-color:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important
}
.xt-root ::selection{color:#f7f8fb;background:#173e7b}

/* Hero — date, title and four-character pair align with P2. */
.xt-content>.xt-card:first-of-type{
  position:relative;isolation:isolate;aspect-ratio:1947/808;min-height:0;overflow:hidden!important;
  color:#f4f6fa!important;background-color:#061127!important;
  background-image:url("https://i.postimg.cc/wTj1DzWf/Image-1787637283266-102.png")!important;
  background-repeat:no-repeat!important;background-position:50% 52%!important;background-size:cover!important
}
.xt-content>.xt-card:first-of-type::after{
  content:"";position:absolute;inset:0;z-index:0;pointer-events:none;
  background:linear-gradient(90deg,transparent 43%,rgba(2,10,26,.04) 60%,rgba(2,10,26,.26))
}
.xt-content>.xt-card:first-of-type>.xt-card-title{
  position:absolute;top:19%;right:3.6%;z-index:2;margin:0!important;padding:0!important;
  color:#f4f6fa!important;font-family:"ZSFT-br","Times New Roman",serif!important;
  font-size:clamp(27px,6.5vw,61px)!important;font-weight:300!important;line-height:.95!important;
  letter-spacing:.12em!important;text-align:right;text-shadow:0 3px 18px rgba(0,6,24,.38)
}
.xt-text-currentDate{font-family:"ZSFT-br","Times New Roman",serif!important;font-variant-numeric:tabular-nums}
.xt-content>.xt-card:first-of-type>.xt-text-currentDate{
  position:absolute;top:6%;right:4.1%;z-index:2;color:rgba(244,247,252,.92)!important;
  font-size:clamp(9px,2vw,18px)!important;font-weight:300!important;line-height:1!important;
  letter-spacing:.26em!important;text-align:right;text-shadow:0 2px 12px rgba(0,6,24,.55)
}
.xt-text-scenePair{
  position:absolute;right:4.2%;bottom:7.5%;z-index:2;max-width:52%;
  color:rgba(244,247,252,.95)!important;font-size:clamp(9px,1.8vw,16px)!important;
  line-height:1.2!important;letter-spacing:.12em!important;text-align:right;text-shadow:0 2px 12px rgba(0,6,24,.7)
}

/* Cold paper page. */
.xt-content>.xt-card:last-of-type{
  position:relative;isolation:isolate;
  padding:clamp(20px,5.2vw,52px) clamp(18px,5vw,48px) clamp(18px,4.5vw,42px)!important;
  overflow:hidden!important;background-color:#edf0f4!important;
  background-image:radial-gradient(circle at 12% 9%,rgba(255,255,255,.32) 0 .55px,transparent .9px),
    radial-gradient(circle at 83% 41%,rgba(18,42,80,.035) 0 .55px,transparent .9px),
    linear-gradient(102deg,rgba(255,255,255,.28),transparent 36%,rgba(20,42,79,.035) 69%,transparent)!important;
  background-size:13px 17px,11px 19px,100% 100%!important
}
.xt-content>.xt-card:last-of-type::before{
  content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:.36;
  background:linear-gradient(180deg,rgba(255,255,255,.3),transparent 18%,rgba(18,42,80,.03) 78%,rgba(255,255,255,.22))
}
.xt-content>.xt-card:last-of-type>.xt-card-title{display:none!important}
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type{
  display:grid!important;grid-template-columns:minmax(0,1.68fr) minmax(0,.82fr)!important;
  align-items:start!important;gap:clamp(16px,4vw,42px)!important;margin:0!important;padding:0!important;background:transparent!important
}
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:last-child{
  padding-left:clamp(14px,3vw,30px)!important;border-left:1px solid rgba(14,40,80,.42)!important
}
.xt-content>.xt-card:last-of-type .xt-card-title{
  margin:0 0 clamp(11px,2vw,20px)!important;padding:0!important;color:#182947!important;background:transparent!important;
  font-family:"ZSFT-br","KingHwaOldSong",serif!important;font-size:clamp(14px,2.55vw,25px)!important;
  font-weight:300!important;line-height:1.08!important;letter-spacing:.06em!important
}
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:first-child>.xt-card-title::after,
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:last-child>.xt-card-title::after{
  display:block;margin-top:.42em;color:#596882;font-family:"ZSFT-br",serif;
  font-size:clamp(7px,.38em,8.5px);font-weight:400;line-height:1.15;letter-spacing:.17em
}
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:first-child>.xt-card-title::after{content:"TODAY'S DIARY";padding-left:3.7em}
.xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:last-child>.xt-card-title::after{content:"RECENT READING / FILM"}

/* Fixed image windows: uploaded source dimensions cannot move the layout. */
.xt-text-journalVisual,.xt-text-recentVisual{
  display:block!important;overflow:hidden!important;color:transparent!important;font-size:0!important;
  line-height:0!important;background-repeat:no-repeat!important
}
.xt-text-journalVisual{
  aspect-ratio:4/3;width:100%;margin-bottom:clamp(14px,2.4vw,23px)!important;
  background-color:#102b62!important;background-image:url("https://i.postimg.cc/44DHppT9/1787629759879.png")!important;
  background-position:50% 38%!important;background-size:cover!important;box-shadow:inset 0 0 0 1px rgba(10,30,67,.34)!important
}
.xt-text-recentVisual{
  aspect-ratio:8/5;width:100%;margin-bottom:clamp(7px,1.2vw,12px)!important;
  background-color:#102b62!important;background-image:url("https://i.postimg.cc/J4zsj8TY/Image-1787637280290-249.png")!important;
  background-position:51% 48%!important;background-size:cover!important;box-shadow:inset 0 0 0 1px rgba(10,30,67,.34)!important
}
.xt-text-journalEntry{
  position:relative;z-index:2;color:#18233a!important;font-size:clamp(10.5px,1.62vw,15px)!important;
  line-height:2.02!important;letter-spacing:.045em!important;text-align:justify
}
/* Compact reading notes. Important values beat the app's default text scale. */
.xt-text-recentTitle{
  margin-top:.08em!important;color:#15294d!important;font-size:clamp(9px,1.48vw,13.5px)!important;
  line-height:1.36!important;letter-spacing:.035em!important
}
.xt-text-recentMeta{
  margin-top:.35em!important;padding-bottom:.45em!important;color:#65728a!important;
  border-bottom:1px dotted rgba(19,49,94,.42)!important;font-family:"ZSFT-br","KingHwaOldSong",serif!important;
  font-size:clamp(7px,.9vw,8.5px)!important;line-height:1.25!important;letter-spacing:.11em!important;text-transform:uppercase
}
.xt-text-recentReflection{
  margin-top:clamp(6px,1vw,10px)!important;color:#2a3952!important;font-size:clamp(8.5px,1.18vw,11px)!important;
  line-height:1.68!important;letter-spacing:.02em!important;text-align:justify
}

/* Full-width separators. */
.xt-content>.xt-card:last-of-type>.xt-divider{
  position:relative;height:1px!important;margin:clamp(20px,4.2vw,40px) 0 clamp(17px,3.2vw,31px)!important;
  overflow:visible!important;border:0!important;background:#183b70!important
}
.xt-content>.xt-card:last-of-type>.xt-divider::before,
.xt-content>.xt-card:last-of-type>.xt-divider::after{
  content:"";position:absolute;top:-2px;width:5px;height:5px;border-radius:50%;background:#0a1833
}
.xt-content>.xt-card:last-of-type>.xt-divider::before{left:0}
.xt-content>.xt-card:last-of-type>.xt-divider::after{right:0}

/* Memorandum sits directly below the reading note in the right column. */
.xt-card:has(>.xt-text-recentReflection)>.xt-text-memo1,
.xt-card:has(>.xt-text-recentReflection)>.xt-text-memo2,
.xt-card:has(>.xt-text-recentReflection)>.xt-text-memo3{
  position:relative;display:block;min-height:0!important;margin:0!important;padding:.42em 0 .42em 2.15em!important;
  color:#273650!important;border-bottom:1px dotted rgba(21,49,91,.3)!important;font-size:clamp(8px,1.05vw,10px)!important;
  line-height:1.5!important
}
.xt-text-memo1,.xt-text-memo2,.xt-text-memo3{
  position:relative;min-height:5.8em!important;padding:.7em 0 .9em 2.35em!important;
  color:#273650!important;border-bottom:1px dotted rgba(21,49,91,.3)!important;
  font-size:clamp(8.5px,1.18vw,11px)!important;line-height:1.62!important
}
.xt-text-memo1::before,.xt-text-memo2::before,.xt-text-memo3::before{
  position:absolute;left:0;top:.72em;color:#173a70;font-family:"ZSFT-br",serif;
  font-size:.9em;font-variant-numeric:tabular-nums;letter-spacing:.06em
}
.xt-text-memo1::before{content:"01."}.xt-text-memo2::before{content:"02."}.xt-text-memo3::before{content:"03."}

/* Two letters stay below the new memorandum spread. */
.xt-card:has(>.xt-row .xt-text-pastLetter){
  position:relative;padding-left:clamp(12px,2vw,20px)!important;border-left:1px solid rgba(17,48,91,.5)!important
}
.xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-card-title::after{
  content:"LETTERS ACROSS TIME";display:block;margin-top:.42em;padding-left:3.8em;color:#596882;
  font-size:clamp(7px,.38em,8.5px);font-weight:400;letter-spacing:.17em
}
.xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row{
  display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:clamp(18px,4vw,42px)!important;
  margin:0!important;padding:0!important;background:transparent!important
}
.xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row>.xt-card{
  position:relative;padding:0 clamp(6px,1.4vw,14px)!important
}
.xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row>.xt-card+.xt-card{
  padding-left:clamp(18px,3.8vw,38px)!important;border-left:1px solid rgba(17,48,91,.32)!important
}
.xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row>.xt-card>.xt-card-title{
  display:inline-block;margin:0 0 clamp(12px,2.2vw,20px)!important;padding:.28em .72em .34em!important;
  color:#f2f4f8!important;background:#14356e!important;font-family:"Huiwen-mincho","KingHwaOldSong",serif!important;
  font-size:clamp(9px,1.35vw,13px)!important;font-weight:400!important;line-height:1.2!important;letter-spacing:.12em!important
}
.xt-text-pastLetter,.xt-text-presentLetter{
  min-height:7.8em!important;color:#24334c!important;font-family:"Huiwen-mincho","KingHwaOldSong",serif!important;
  font-size:clamp(9px,1.32vw,12.5px)!important;line-height:2!important;letter-spacing:.03em!important;text-align:justify
}
.xt-text-pastSignature,.xt-text-presentSignature{
  margin-top:clamp(10px,1.8vw,18px)!important;color:#172b4d!important;
  font-family:"Huiwen-mincho","KingHwaOldSong",serif!important;font-size:clamp(10px,1.45vw,14px)!important;
  line-height:1.4!important;letter-spacing:.08em!important;text-align:right
}
.xt-text-pastDate{
  margin-top:.35em!important;color:#4b5c76!important;font-family:"ZSFT-br",serif!important;
  font-size:clamp(8px,.92vw,9.5px)!important;font-weight:300!important;line-height:1.3!important;
  letter-spacing:.16em!important;text-align:right
}
.xt-footer{
  margin:clamp(22px,4vw,38px) 0 0!important;padding:clamp(11px,1.8vw,17px) 0 0!important;
  color:#4d5e79!important;background:transparent!important;border:0!important;
  border-top:1px solid rgba(19,49,93,.22)!important;font-family:"ZSFT-br",serif!important;
  font-size:clamp(8px,.92vw,9.5px)!important;font-weight:300!important;line-height:1.2!important;
  letter-spacing:.24em!important;text-align:right
}

@keyframes yh-page-in{from{opacity:.72;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
.xt-content>.xt-card:last-of-type{animation:yh-page-in 220ms ease-out both}

@media(max-width:520px){
  .xt-content>.xt-card:last-of-type{padding:16px 14px 17px!important}
  .xt-content>.xt-card:last-of-type>.xt-row:first-of-type{grid-template-columns:minmax(0,1.68fr) minmax(0,.82fr)!important;gap:12px!important}
  .xt-content>.xt-card:last-of-type>.xt-row:first-of-type>.xt-card:last-child{padding-left:11px!important}
  .xt-content>.xt-card:last-of-type .xt-card-title{font-size:clamp(10.5px,3.25vw,16px)!important;letter-spacing:.025em!important}
  .xt-text-journalEntry{font-size:clamp(10.5px,2.75vw,12px)!important;line-height:1.9!important}
  .xt-text-recentTitle{font-size:clamp(8px,2.15vw,9.5px)!important}
  .xt-text-recentMeta{margin-top:.22em!important;font-size:clamp(6.5px,1.72vw,8px)!important}
  .xt-text-recentReflection{margin-top:5px!important;font-size:clamp(8px,2.05vw,9.2px)!important;line-height:1.62!important}
  .xt-card:has(>.xt-text-recentReflection)>.xt-text-memo1,
  .xt-card:has(>.xt-text-recentReflection)>.xt-text-memo2,
  .xt-card:has(>.xt-text-recentReflection)>.xt-text-memo3{
    font-size:clamp(7.5px,1.95vw,8.8px)!important;padding-left:2em!important
  }
  .xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row{gap:10px!important}
  .xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row>.xt-card{padding-right:6px!important}
  .xt-card:has(>.xt-row .xt-text-pastLetter)>.xt-row>.xt-card+.xt-card{padding-left:12px!important}
  .xt-text-pastLetter,.xt-text-presentLetter{
    min-height:9.4em!important;font-size:clamp(9px,2.3vw,10.2px)!important;line-height:1.86!important
  }
}
@media(prefers-reduced-motion:reduce){.xt-content>.xt-card:last-of-type{animation:none!important}}

xinshengLayout:
# 夜航书札 · 文艺杂志内页 v7
@card "TREASURE"
  @text currentDate
  @text scenePair
@endcard

@card
  @row 2
    @card "01 今日手札"
      @text journalVisual
      @text journalEntry
    @endcard
    @card "02 近日读影"
      @text recentVisual
      @text recentTitle
      @text recentMeta
      @text recentReflection
      @text memo1
      @text memo2
      @text memo3
    @endcard
  @endrow

  @divider

  @card "03 隔年书"
    @row 2
      @card "旧时来札"
        @text pastLetter
        @text pastSignature
        @text pastDate
      @endcard
      @card "今宵复笺"
        @text presentLetter
        @text presentSignature
      @endcard
    @endrow
  @endcard

  @footer BITS OF BLISS · PRIVATE EDITION
@endcard

